validator:
function validate(input) {
  const [{ Employees = [] }] = input;
  const boss = new Map();
  for (const row of Employees) {
    if (row.some((v) => v === null)) return 'Employees rows may not contain null.';
    if (boss.has(row[0])) return `employee_id ${row[0]} appears twice.`;
    boss.set(row[0], row[2]);
  }
  for (const [id, manager] of boss) if (!boss.has(manager)) return `Employee ${id} has a manager_id that is not an employee.`;
  if (boss.has(1) && boss.get(1) !== 1) return 'Employee 1 must be their own manager.';
  for (const id of boss.keys()) {
    let at = id, steps = 0;
    while (at !== 1 && steps <= boss.size) { at = boss.get(at); steps++; }
    if (at === 1 && steps > 3) return `Employee ${id} is ${steps} steps from the head; at most 3 are allowed.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const names = ['Boss', 'Alice', 'Bob', 'Daniel', 'Luis', 'John', 'Angela', 'Robert', 'Mia', 'Omar', 'Yuki', 'Ines'];
  const small = size === 'small';
  const count = small ? pick(9) : 2000;
  const pool = small ? [2, 3, 4, 5, 6, 7, 8, 9, 10, 13, 77] : Array.from({ length: 3000 }, (_, i) => i + 2);
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const rows = [], tree = [], outside = [];
  // The head is usually present; employees then join its tree (depth at most 3) or form groups that never reach it.
  const hasHead = count > 0 && (!small || rand() < 0.85);
  if (hasHead) { rows.push([1, 'Boss', 1]); tree.push([1, 0]); }
  for (let i = 0; rows.length < count; i++) {
    const id = pool[i], name = names[pick(names.length)], r = rand();
    const open = tree.filter(([, depth]) => depth < 3);
    if (r < 0.6 && open.length) {
      const [manager, depth] = open[pick(open.length)];
      rows.push([id, name, manager]);
      tree.push([id, depth + 1]);
    } else if (r < 0.75 || !outside.length) {
      rows.push([id, name, id]);
      outside.push(rows.length - 1);
    } else {
      const other = outside[pick(outside.length)];
      rows.push([id, name, rows[other][0]]);
      // Sometimes a self-managed employee is redirected to the newcomer, closing a loop of two.
      if (rows[other][2] === rows[other][0] && rand() < 0.3) rows[other][2] = id;
      outside.push(rows.length - 1);
    }
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Employees: rows }];
}
